if [[ ${1:-} == --extract ]]; then
    [[ $# == 2 && -n $2 && ! -e $2 && ! -L $2 ]] || {
        echo '--extract requires a new, nonexistent destination directory.' >&2
        exit 1
    }
    mkdir -m 700 -- "$2"
    cp -R "$bundle_dir/source/." "$2/"
    echo "Bundled sources extracted to $2; no service was installed."
    exit 0
fi
